arguments.prompt:
You are implementing a Blazor Web App shipment tracker for a logistics company. The project has already been scaffolded at `/tmp/sv-137576b4836e48c19e27fe2ea017b517/ShipmentTracker/` using `dotnet new blazor -int Auto -ai -au Individual`.

The project structure:
- `ShipmentTracker/` - server project
- `ShipmentTracker.Client/` - client/WebAssembly project

## Requirements
- Dispatchers view a list of shipments with status and destination
- Customers check their shipment status and estimated delivery
- Every page has interactive controls
- Authentication with individual accounts (already scaffolded)

## What to implement

### 1. Remove template demo pages
Delete these files from `ShipmentTracker.Client/Pages/`:
- `Counter.razor`
- `Weather.razor`

### 2. Create shared models in the Client project

Create `ShipmentTracker.Client/Models/Shipment.cs`:
```csharp
namespace ShipmentTracker.Client.Models;

public class Shipment
{
    public int Id { get; set; }
    public string TrackingNumber { get; set; } = string.Empty;
    public string Origin { get; set; } = string.Empty;
    public string Destination { get; set; } = string.Empty;
    public ShipmentStatus Status { get; set; }
    public DateTime ShippedDate { get; set; }
    public DateTime EstimatedDelivery { get; set; }
    public string CustomerEmail { get; set; } = string.Empty;
    public string RecipientName { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
}

public enum ShipmentStatus
{
    Pending,
    PickedUp,
    InTransit,
    OutForDelivery,
    Delivered,
    Delayed
}
```

### 3. Create service interface in the Client project

Create `ShipmentTracker.Client/Services/IShipmentService.cs`:
```csharp
namespace ShipmentTracker.Client.Services;

using ShipmentTracker.Client.Models;

public interface IShipmentService
{
    Task<List<Shipment>> GetAllShipmentsAsync();
    Task<Shipment?> GetShipmentByTrackingNumberAsync(string trackingNumber);
    Task<List<Shipment>> GetShipmentsByCustomerAsync(string email);
    Task UpdateShipmentStatusAsync(int id, ShipmentStatus status);
}
```

### 4. Create client-side HTTP implementation

Create `ShipmentTracker.Client/Services/ShipmentHttpService.cs`:
```csharp
using System.Net.Http.Json;
using ShipmentTracker.Client.Models;

namespace ShipmentTracker.Client.Services;

public class ShipmentHttpService : IShipmentService
{
    private readonly HttpClient _http;

    public ShipmentHttpService(HttpClient http)
    {
        _http = http;
    }

    public async Task<List<Shipment>> GetAllShipmentsAsync()
    {
        return await _http.GetFromJsonAsync<List<Shipment>>("api/shipments") ?? [];
    }

    public async Task<Shipment?> GetShipmentByTrackingNumberAsync(string trackingNumber)
    {
        return await _http.GetFromJsonAsync<Shipment?>($"api/shipments/track/{trackingNumber}");
    }

    public async Task<List<Shipment>> GetShipmentsByCustomerAsync(string email)
    {
        return await _http.GetFromJsonAsync<List<Shipment>>($"api/shipments/customer/{Uri.EscapeDataString(email)}") ?? [];
    }

    public async Task UpdateShipmentStatusAsync(int id, ShipmentStatus status)
    {
        await _http.PutAsJsonAsync($"api/shipments/{id}/status", status);
    }
}
```

### 5. Register services in Client Program.cs

Edit `ShipmentTracker.Client/Program.cs` to:
```csharp
using Microsoft.AspNetCore.Components.WebAssembly.Hosting;
using ShipmentTracker.Client.Services;

var builder = WebAssemblyHostBuilder.CreateDefault(args);

builder.Services.AddAuthorizationCore();
builder.Services.AddCascadingAuthenticationState();
builder.Services.AddAuthenticationStateDeserialization();

builder.Services.AddHttpClient<IShipmentService, ShipmentHttpService>(client =>
{
    client.BaseAddress = new Uri(builder.HostEnvironment.BaseAddress);
});

await builder.Build().RunAsync();
```

### 6. Create server-side service implementation

Create `ShipmentTracker/Services/ShipmentServerService.cs`:
```csharp
using ShipmentTracker.Client.Models;
using ShipmentTracker.Client.Services;

namespace ShipmentTracker.Services;

public class ShipmentServerService : IShipmentService
{
    // In-memory seed data for demonstration
    private static readonly List<Shipment> _shipments =
    [
        new() { Id = 1, TrackingNumber = "TRK-001-2026", Origin = "New York, USA", Destination = "London, UK", Status = ShipmentStatus.InTransit, ShippedDate = DateTime.Parse("2026-06-18"), EstimatedDelivery = DateTime.Parse("2026-06-25"), CustomerEmail = "alice@example.com", RecipientName = "Alice Johnson", Description = "Electronics - Laptop" },
        new() { Id = 2, TrackingNumber = "TRK-002-2026", Origin = "Shanghai, China", Destination = "Los Angeles, USA", Status = ShipmentStatus.Pending, ShippedDate = DateTime.Parse("2026-06-20"), EstimatedDelivery = DateTime.Parse("2026-07-01"), CustomerEmail = "bob@example.com", RecipientName = "Bob Smith", Description = "Furniture - Office Desk" },
        new() { Id = 3, TrackingNumber = "TRK-003-2026", Origin = "Berlin, Germany", Destination = "Tokyo, Japan", Status = ShipmentStatus.OutForDelivery, ShippedDate = DateTime.Parse("2026-06-15"), EstimatedDelivery = DateTime.Parse("2026-06-23"), CustomerEmail = "carol@example.com", RecipientName = "Carol Tanaka", Description = "Auto Parts" },
        new() { Id = 4, TrackingNumber = "TRK-004-2026", Origin = "Sydney, Australia", Destination = "Mumbai, India", Status = ShipmentStatus.Delivered, ShippedDate = DateTime.Parse("2026-06-10"), EstimatedDelivery = DateTime.Parse("2026-06-20"), CustomerEmail = "alice@example.com", RecipientName = "Dev Patel", Description = "Textiles - Cotton Fabric" },
        new() { Id = 5, TrackingNumber = "TRK-005-2026", Origin = "São Paulo, Brazil", Destination = "Paris, France", Status = ShipmentStatus.Delayed, ShippedDate = DateTime.Parse("2026-06-12"), EstimatedDelivery = DateTime.Parse("2026-06-28"), CustomerEmail = "emma@example.com", RecipientName = "Emma Dupont", Description = "Agricultural Products" },
        new() { Id = 6, TrackingNumber = "TRK-006-2026", Origin = "Toronto, Canada", Destination = "Dubai, UAE", Status = ShipmentStatus.PickedUp, ShippedDate = DateTime.Parse("2026-06-22"), EstimatedDelivery = DateTime.Parse("2026-06-30"), CustomerEmail = "bob@example.com", RecipientName = "Fatima Al-Hassan", Description = "Medical Supplies" },
    ];

    public Task<List<Shipment>> GetAllShipmentsAsync()
    {
        return Task.FromResult(_shipments.ToList());
    }

    public Task<Shipment?> GetShipmentByTrackingNumberAsync(string trackingNumber)
    {
        var shipment = _shipments.FirstOrDefault(s => s.TrackingNumber.Equals(trackingNumber, StringComparison.OrdinalIgnoreCase));
        return Task.FromResult(shipment);
    }

    public Task<List<Shipment>> GetShipmentsByCustomerAsync(string email)
    {
        var shipments = _shipments.Where(s => s.CustomerEmail.Equals(email, StringComparison.OrdinalIgnoreCase)).ToList();
        return Task.FromResult(shipments);
    }

    public Task UpdateShipmentStatusAsync(int id, ShipmentStatus status)
    {
        var shipment = _shipments.FirstOrDefault(s => s.Id == id);
        if (shipment != null)
        {
            shipment.Status = status;
        }
        return Task.CompletedTask;
    }
}
```

### 7. Add API endpoints and register server service in server Program.cs

Edit `ShipmentTracker/Program.cs`. After the `app.MapAdditionalIdentityEndpoints();` line but before `app.Run();`, add:

```csharp
// Shipment API endpoints
var shipments = app.MapGroup("api/shipments").RequireAuthorization();

shipments.MapGet("", async (IShipmentService service) =>
    await service.GetAllShipmentsAsync());

shipments.MapGet("track/{trackingNumber}", async (string trackingNumber, IShipmentService service) =>
{
    var shipment = await service.GetShipmentByTrackingNumberAsync(trackingNumber);
    return shipment is not null ? Results.Ok(shipment) : Results.NotFound();
});

shipments.MapGet("customer/{email}", async (string email, IShipmentService service) =>
    await service.GetShipmentsByCustomerAsync(email));

shipments.MapPut("{id}/status", async (int id, ShipmentStatus status, IShipmentService service) =>
{
    await service.UpdateShipmentStatusAsync(id, status);
    return Results.NoContent();
});
```

Also add these using statements at the top of server Program.cs:
```csharp
using ShipmentTracker.Client.Models;
using ShipmentTracker.Client.Services;
using ShipmentTracker.Services;
```

And register the service before `var app = builder.Build();`:
```csharp
builder.Services.AddSingleton<IShipmentService, ShipmentServerService>();
```

