@code {
    private List<Shipment> shipments = [];
    private bool isLoading = true;
    private string filterText = string.Empty;
    private string filterStatus = string.Empty;
    private string sortColumn = nameof(Shipment.TrackingNumber);
    private bool sortAscending = true;

    protected override async Task OnInitializedAsync()
    {
        await LoadData();
    }

    private async Task LoadData()
    {
        isLoading = true;
        shipments = await ShipmentService.GetAllShipmentsAsync();
        isLoading = false;
    }

    private async Task RefreshData()
    {
        await LoadData();
    }

    private IEnumerable<Shipment> FilteredShipments
    {
        get
        {
            var result = shipments.AsEnumerable();

            if (!string.IsNullOrWhiteSpace(filterText))
            {
                result = result.Where(s =>
                    s.Destination.Contains(filterText, StringComparison.OrdinalIgnoreCase) ||
                    s.Origin.Contains(filterText, StringComparison.OrdinalIgnoreCase) ||
                    s.TrackingNumber.Contains(filterText, StringComparison.OrdinalIgnoreCase));
            }

            if (!string.IsNullOrWhiteSpace(filterStatus) && Enum.TryParse<ShipmentStatus>(filterStatus, out var status))
            {
                result = result.Where(s => s.Status == status);
            }

            result = sortColumn switch
            {
                nameof(Shipment.TrackingNumber) => sortAscending ? result.OrderBy(s => s.TrackingNumber) : result.OrderByDescending(s => s.TrackingNumber),
                nameof(Shipment.Origin) => sortAscending ? result.OrderBy(s => s.Origin) : result.OrderByDescending(s => s.Origin),
                nameof(Shipment.Destination) => sortAscending ? result.OrderBy(s => s.Destination) : result.OrderByDescending(s => s.Destination),
                nameof(Shipment.Status) => sortAscending ? result.OrderBy(s => s.Status) : result.OrderByDescending(s => s.Status),
                _ => result
            };

            return result;
        }
    }

    private void SortBy(string column)
    {
        if (sortColumn == column)
        {
            sortAscending = !sortAscending;
        }
        else
        {
            sortColumn = column;
            sortAscending = true;
        }
    }

    private string SortIndicator(string column)
    {
        if (sortColumn != column) return "";
        return sortAscending ? "▲" : "▼";
    }

    private async Task OnStatusChange(Shipment shipment, ChangeEventArgs e)
    {
        if (Enum.TryParse<ShipmentStatus>(e.Value?.ToString(), out var newStatus))
        {
            await ShipmentService.UpdateShipmentStatusAsync(shipment.Id, newStatus);
            shipment.Status = newStatus;
        }
    }

    private static string GetStatusBadgeClass(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Delivered => "bg-success",
        ShipmentStatus.InTransit => "bg-primary",
        ShipmentStatus.OutForDelivery => "bg-info text-dark",
        ShipmentStatus.Delayed => "bg-danger",
        ShipmentStatus.PickedUp => "bg-secondary",
        ShipmentStatus.Pending => "bg-warning text-dark",
        _ => "bg-light text-dark"
    };
}
